use vstd::prelude::*;

verus! {

fn linear_search(a: &Vec<i32>, e: i32) -> (res: usize)
    ensures
        // res is always in-bounds or equal to len (not found)
        res <= a.len(),

        // if we return an in-bounds index, it is a correct match
        res < a.len() ==> a[res] == e,

        // if we return len, then no element equals e
        res == a.len() ==> (forall|j: int| 0 <= j < a.len() ==> a[j] != e),

        // if we return an in-bounds index, it's the first occurrence
        res < a.len() ==> (forall|j: int| 0 <= j < res ==> a[j] != e),
{
    for (i, &x) in a.iter().enumerate()
        invariant
            // i stays within 0..=len
            i <= a.len(),
            // all earlier elements are not equal to e (otherwise we'd have returned)
            forall|j: int| 0 <= j < i ==> a[j] != e,
    {
        if x == e {
            // connect iterator element `x` to indexing into `a`
            assert(a[i] == x);

            // since the loop invariant states no earlier match exists:
            assert(forall|j: int| 0 <= j < i ==> a[j] != e);

            return i;
        }
    }
    a.len()
}

} // verus!

